// D1 is the deployment target this project is built for (ADR 0002), and it
// is not plain SQLite. The migration SQL in this directory is generated by
// drizzle-kit, which targets SQLite generally and emits statements D1 refuses
// — so "it applied locally" proves nothing about the one database that
// matters, and the failure surfaces at `wrangler d1 migrations apply`, which
// is the slowest possible place to learn it.
//
// The specific one that bit: every table rebuild drizzle-kit writes is
// wrapped in `PRAGMA foreign_keys=OFF/ON`. D1 runs every statement inside an
// implicit transaction and documents that a user query cannot change that
// setting during a migration, so both statements fail there. This schema
// declares no foreign keys, so the pragma was pure ceremony and was removed;
// if one is ever added, `PRAGMA defer_foreign_keys = on` is the D1-safe form,
// which is why that spelling is allowed below and the other is not.
//
// Deleting a line from generated output only stays deleted if something
// notices when it comes back, and the next `ALTER COLUMN` will bring it back.

import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { expect, it } from "vitest";

const SQLITE_MIGRATIONS = fileURLToPath(
  new URL("../migrations/sqlite/", import.meta.url),
);

/**
 * `defer_foreign_keys` is the one pragma D1 documents as settable, so it is
 * matched and allowed; anything else is rejected by name.
 */
const FORBIDDEN_PRAGMA = /PRAGMA\s+(?!defer_foreign_keys\b)(\w+)/gi;

function migrationFiles(): string[] {
  return readdirSync(SQLITE_MIGRATIONS)
    .filter((name) => name.endsWith(".sql"))
    .sort();
}

it("the sqlite migrations are readable, so this guard is not passing on an empty list", () => {
  expect(migrationFiles().length).toBeGreaterThan(0);
});

it("no migration uses a PRAGMA that D1 refuses during a migration", () => {
  for (const name of migrationFiles()) {
    const sql = readFileSync(`${SQLITE_MIGRATIONS}${name}`, "utf8")
      // Comments explain why a pragma is absent; they are not statements.
      .replace(/^\s*--.*$/gm, "");

    const found = [...sql.matchAll(FORBIDDEN_PRAGMA)].map((m) => m[1]);
    expect(found, `${name} uses PRAGMA ${found.join(", ")}`).toEqual([]);
  }
});
